contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Call rate on arbitrary vault and asset; if call succeeds (doesn't revert), it must not increase address(c).balance.
    // We require that the provided elapsed-sensitive storage won't underflow by bounding block.timestamp related behavior is not possible here,
    // so keep parameters unconstrained; we just check balance invariant.
    function run(address vault, address asset) public {
        uint256 balBefore = address(c).balance;

        bool reverted;
        uint256 latest = c.rate(vault, asset); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balAfter = address(c).balance;

        // General rule: if rate call succeeded, it must not increase contract's Ether balance.
        assert(reverted || balAfter <= balBefore);
    }

    receive() external payable { }
}

